// src/pages/Dashboard.jsx
import { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { getMesas, getPedidos, getProductos } from "../services/api";
import "./Dashboard.css";

export default function Dashboard() {
  const [mesas, setMesas] = useState([]);
  const [pedidos, setPedidos] = useState([]);
  const [productos, setProductos] = useState([]);
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();

  useEffect(() => {
    const cargarDatos = async () => {
      try {
        const [dataMesas, dataPedidos, dataProductos] = await Promise.all([
          getMesas(),
          getPedidos(),
          getProductos(),
        ]);
        setMesas(dataMesas);
        setPedidos(dataPedidos);
        setProductos(dataProductos);
      } catch (err) {
        console.error(err);
        if (err.message.includes("401")) {
          navigate("/login");
        }
      } finally {
        setLoading(false);
      }
    };
    cargarDatos();
  }, [navigate]);

  const cerrarSesion = () => {
    localStorage.removeItem("access_token");
    localStorage.removeItem("refresh_token");
    navigate("/login");
  };

  if (loading) {
    return <div className="loader">Cargando SOFTFOOD...</div>;
  }

  return (
    <div className="dashboard">
      <div className="dashboard-bg"></div>
      <div className="dashboard-overlay"></div>

      <div className="dashboard-content">
        <header className="dashboard-header">
          <h1 className="dashboard-title">SOFTFOOD</h1>
          <p className="dashboard-subtitle">Panel del Restaurante</p>
        </header>

        <div className="stats-grid">
          <div className="stat-card">
            <div className="icon">Table</div>
            <h3>Mesas Ocupadas</h3>
            <p className="number">{mesas.filter(m => m.estado === "ocupada").length}</p>
            <span>Total: {mesas.length}</span>
          </div>

          <div className="stat-card">
            <div className="icon">Cart</div>
            <h3>Pedidos Hoy</h3>
            <p className="number">{pedidos.length}</p>
            <span>Activos</span>
          </div>

          <div className="stat-card">
            <div className="icon">Food</div>
            <h3>Productos</h3>
            <p className="number">{productos.length}</p>
            <span>En menú</span>
          </div>

          <div className="stat-card">
            <div className="icon">Clock</div>
            <h3>Hora</h3>
            <p className="number">{new Date().toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</p>
            <span>{new Date().toLocaleDateString('es-ES', {weekday: 'long', day: 'numeric', month: 'long'})}</span>
          </div>
        </div>

        <button onClick={cerrarSesion} className="logout-btn">
          Cerrar sesión
        </button>
      </div>
    </div>
  );
}
